# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZEL DURUMLARIN CEBİRSEL İFADEYE DÖNÜŞTÜRÜLMESİ (MAT.6.2.1)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Temel Cebirsel Dönüşümler (Sayı = x)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Bir sayının 5 fazlası ➔ x + 5</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Bir sayının 3 eksiği ➔ x − 3</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Bir sayının 4 katı ➔ 4 · x = 4x</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Bir sayının yarısı ➔ x / 2</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Bir sayının karesi ➔ x²</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Değişken: x, y, a, n, k gibi harflerdir.</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Sıra Farkına Dikkat! (Önce Hangisi?)</text>\n  <rect x="378" y="88" width="284" height="62" rx="6" fill="#fef9c3" stroke="#ca8a04"/>\n  <text x="520" y="110" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">1) «Bir sayının 3 katının 2 fazlası»</text>\n  <text x="520" y="134" text-anchor="middle" font-size="13" font-weight="bold" fill="#713f12">Önce 3 ile çarp, sonra 2 ekle ➔ 3x + 2</text>\n\n  <rect x="378" y="160" width="284" height="62" rx="6" fill="#ffedd5" stroke="#ea580c"/>\n  <text x="520" y="182" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">2) «Bir sayının 2 fazlasının 3 katı»</text>\n  <text x="520" y="206" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Önce 2 ekle (parantez!), sonra 3 katı ➔ 3(x + 2)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CEBİRSEL İFADENİN BİLEŞENLERİ: 5x − 3y + 8 ÖRNEĞİ</text>\n  <rect x="25" y="48" width="650" height="54" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="82" text-anchor="middle" font-size="20" font-weight="bold" fill="#0e7490">Cebirsel İfade:   5x   −   3y   +   8</text>\n\n  <rect x="25" y="114" width="152" height="126" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="101" y="138" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Değişkenler</text>\n  <text x="101" y="168" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e3a8a">x ve y</text>\n  <text x="101" y="196" text-anchor="middle" font-size="10.5" fill="#475569">Bilinmeyen sayıları</text>\n  <text x="101" y="212" text-anchor="middle" font-size="10.5" fill="#475569">temsil eden harfler</text>\n\n  <rect x="191" y="114" width="152" height="126" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="267" y="138" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Terimler (3 adet)</text>\n  <text x="267" y="168" text-anchor="middle" font-size="14" font-weight="bold" fill="#14532d">5x ,  −3y ,  +8</text>\n  <text x="267" y="196" text-anchor="middle" font-size="10.5" fill="#475569">+ ve − işaretleriyle</text>\n  <text x="267" y="212" text-anchor="middle" font-size="10.5" fill="#475569">ayrılan her parça</text>\n\n  <rect x="357" y="114" width="152" height="126" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="433" y="138" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">3. Katsayılar</text>\n  <text x="433" y="168" text-anchor="middle" font-size="14" font-weight="bold" fill="#581c87">5 ,  −3 ,  +8</text>\n  <text x="433" y="196" text-anchor="middle" font-size="10.5" fill="#475569">Toplamı: 5 − 3 + 8 = 10</text>\n  <text x="433" y="212" text-anchor="middle" font-size="10.5" fill="#475569">(Sabit terim de katsayıdır!)</text>\n\n  <rect x="523" y="114" width="152" height="126" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="599" y="138" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be123c">4. Sabit Terim</text>\n  <text x="599" y="168" text-anchor="middle" font-size="16" font-weight="bold" fill="#9f1239">+8</text>\n  <text x="599" y="196" text-anchor="middle" font-size="10.5" fill="#475569">Yanında değişken (harf)</text>\n  <text x="599" y="212" text-anchor="middle" font-size="10.5" fill="#475569">bulunmayan terim</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BENZER TERİMLER VE CEBİRSEL İFADENİN DEĞERİNİ BULMA</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Benzer Terimler</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Değişkenleri (harfleri) ve bu harflerin</text>\n  <text x="182" y="120" text-anchor="middle" font-size="11.5" fill="#1e3a8a">kuvvetleri birebir aynı olan terimlerdir.</text>\n  <text x="182" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">✓ 4a ile −7a (Benzerdir)</text>\n  <text x="182" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">✓ 3xy ile 9yx (Benzerdir)</text>\n  <text x="182" y="194" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">✗ 5x ile 5x² (Kuvvet farklı, benzer değil)</text>\n  <text x="182" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">✗ 6a ile 6b (Harf farklı, benzer değil)</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Cebirsel İfadenin Değerini Bulma</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11.5" fill="#14532d">• Değişken yerine verilen sayı konularak</text>\n  <text x="517" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">işlem önceliğine göre sonuç hesaplanır.</text>\n  <text x="517" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Örnek: x = 4 için  3x² − 5x + 2  değeri:</text>\n  <text x="517" y="174" text-anchor="middle" font-size="12" fill="#14532d">= 3 · (4²) − 5 · 4 + 2</text>\n  <text x="517" y="196" text-anchor="middle" font-size="12" fill="#14532d">= 3 · 16 − 20 + 2 = 48 − 20 + 2</text>\n  <text x="517" y="218" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sonuç = 30</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
